@import "tailwindcss";

@theme inline {
  --color-gold-light: #F5F0E9; /* Swan Wing */
  --color-gold: #E0C58F;       /* Quicksand */
  --color-gold-dark: #D9CBC2;  /* Shellstone */
  --color-navy-light: #3C507D; /* Sapphire */
  --color-navy-mid: #1A2F45;
  --color-navy: #112250;       /* Royal Blue */
  --color-whatsapp: #25D366;
  --color-whatsapp-dark: #128C7E;

  --font-display: var(--font-cormorant);
  --font-accent: var(--font-playfair);
  --font-sans: var(--font-dm-sans);
  --font-label: var(--font-montserrat);

  --ease-premium: cubic-bezier(0.16, 1, 0.3, 1);

  --animate-x-slider: x-slider 30s linear infinite;
  @keyframes x-slider {
    0% { transform: translateX(0%); }
    100% { transform: translateX(calc(-50% - 1rem)); }
  }
}

:root {
  --background: #112250; /* Royal Blue */
  --foreground: #F5F0E9; /* Swan Wing */
}

body {
  background-color: var(--background);
  color: var(--foreground);
  font-family: var(--font-dm-sans), sans-serif;
  overflow-x: hidden;
}

/* Custom Utilities */
.text-gold-gradient {
  background: linear-gradient(135deg, #E0C58F 0%, #F5F0E9 50%, #D9CBC2 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
}

.bg-navy-cinematic {
  background: linear-gradient(135deg, #112250 0%, #3C507D 40%, #0a1520 100%);
}

.gold-border-glow {
  box-shadow: 0 0 20px rgba(201,168,71,0.15);
}

@keyframes pulse-green {
  0%, 100% { box-shadow: 0 4px 20px rgba(37,211,102,0.5); }
  50% { box-shadow: 0 4px 40px rgba(37,211,102,0.8), 0 0 0 8px rgba(37,211,102,0.1); }
}

.animate-pulse-green {
  animation: pulse-green 2s infinite;
}

.animate-x-slider:hover {
  animation-play-state: paused;
}

import type { Metadata } from "next";
import { Cormorant_Garamond, Playfair_Display, DM_Sans, Montserrat } from "next/font/google";
