  tag: string;
  tagType: "gold" | "navy";
  specs: string[];
  features: string[];
  price: string;
  offer: string;
  waText: string;
}

const ProjectCard = ({ name, location, tag, tagType, specs, features, price, offer, waText }: ProjectCardProps) => {
